"use strict";(self.webpackChunksalat_e_mustaqeem_client=self.webpackChunksalat_e_mustaqeem_client||[]).push([[482],{10482:e=>{e.exports=JSON.parse('{"meta":{"title":"Agents IA - iMuslim Life","description":"Demandez \xe0 Claude, ChatGPT, Gemini ou Copilot les horaires de pri\xe8re du jour, la Qibla et la date h\xe9girienne. Connectez notre serveur MCP gratuit en une minute, sans cl\xe9 API."},"chip":"Nouveau : serveur MCP","h1":"Les heures de pri\xe8re pour votre assistant IA","lede":"Connectez Claude, ChatGPT, Gemini ou Copilot au serveur d\u2019heures de pri\xe8re Muslim Companion. Votre assistant r\xe9pond alors avec de vraies heures calcul\xe9es pour votre ville et votre m\xe9thode, pas une supposition.","copy":"Copier","copied":"Copi\xe9","toolsH2":"Ce que votre assistant peut faire","toolsSub":"Six outils en lecture seule. Les heures sont calcul\xe9es dans le fuseau horaire du lieu, avec la m\xe9thode de calcul et l\u2019\xe9cole pour l\u2019Asr de votre choix.","tools":{"prayer":{"title":"Heures de pri\xe8re pour n\u2019importe quel jour","text":"Fajr, lever du soleil, Dhuhr, Asr, Maghrib et Isha pour un lieu et une date, en heure locale, avec la date h\xe9girienne."},"next":{"title":"Prochaine pri\xe8re","text":"Quelle est la prochaine pri\xe8re, son heure et dans combien de minutes."},"find":{"title":"Trouver un lieu","text":"Transforme une ville ou une adresse en coordonn\xe9es et en fuseau horaire."},"hijri":{"title":"Date h\xe9girienne","text":"La date islamique de n\u2019importe quelle date gr\xe9gorienne."},"qibla":{"title":"Direction de la qibla","text":"La direction de la Kaaba depuis n\u2019importe quel lieu, en degr\xe9s et en point cardinal."},"methods":{"title":"M\xe9thodes de calcul","text":"ISNA, Ligue islamique mondiale, Umm al-Qura, Karachi et 11 autres, avec l\u2019Asr hanafite ou standard."}},"setupH2":"Configuration","tabDevelopers":"D\xe9veloppeurs","claude":{"s1":"Sur <b>claude.ai</b> ou dans <b>Claude Desktop</b>, ouvrez <b>Settings \u2192 Connectors</b>.","s2":"Choisissez <b>Add custom connector</b>. Nommez-le <b>Muslim Companion</b> et collez l\u2019URL du serveur ci-dessous.","s3":"Enregistrez. Dans une conversation, activez le connecteur (depuis le menu des outils) et demandez : <i>\xab \xc0 quelle heure est le Maghrib \xe0 Toronto aujourd\u2019hui ? \xbb</i>","note":"Les connecteurs personnalis\xe9s d\xe9pendent de votre abonnement Claude. Pour Claude Code, lancez plut\xf4t la commande ci-dessous."},"chatgpt":{"s1":"Dans ChatGPT, ouvrez <b>Settings \u2192 Apps & Connectors</b>, puis <b>Advanced settings</b>, et activez <b>Developer mode</b>.","s2":"Choisissez <b>Create</b> (nouveau connecteur). Nommez-le <b>Muslim Companion</b>, collez l\u2019URL du serveur ci-dessous et choisissez <b>No authentication</b>.","s3":"Dans une nouvelle conversation, ajoutez le connecteur et demandez : <i>\xab Quelles sont les heures de pri\xe8re aujourd\u2019hui \xe0 Londres, Asr hanafite ? \xbb</i>","note":"Les connecteurs du mode d\xe9veloppeur d\xe9pendent de votre abonnement ChatGPT, et les noms des menus peuvent changer d\u2019une version \xe0 l\u2019autre."},"gemini":{"s1":"Ouvrez <b>~/.gemini/settings.json</b> (cr\xe9ez-le s\u2019il n\u2019existe pas).","s2":"Ajoutez l\u2019entr\xe9e <b>muslim-companion</b> ci-dessous sous <b>mcpServers</b>, puis red\xe9marrez Gemini CLI.","s3":"Lancez <b>/mcp</b> pour v\xe9rifier la connexion, puis posez vos questions sur les heures de pri\xe8re."},"vscode":{"s1":"Dans votre projet, cr\xe9ez <b>.vscode/mcp.json</b> (ou lancez <b>MCP: Add Server</b> depuis la Command Palette et choisissez <b>HTTP</b>).","s2":"Collez la configuration ci-dessous et cliquez sur <b>Start</b> au-dessus de l\u2019entr\xe9e du serveur.","s3":"Dans Copilot Chat, passez en mode <b>Agent</b> et posez vos questions sur les heures de pri\xe8re."},"dev":{"s1":"Tout client MCP peut se connecter : le serveur utilise <b>Streamable HTTP</b>, est sans \xe9tat et ne demande aucune cl\xe9 d\u2019API.","s2":"Appelez un outil avec une requ\xeate JSON-RPC <b>POST</b>, comme dans l\u2019exemple ci-dessous.","s3":"Lisez <a>llms.txt</a> pour un court aper\xe7u \xe9crit pour les mod\xe8les de langage.","note":"Limites : 60 requ\xeates par minute et 600 par heure et par client. Mettez en cache les heures de la journ\xe9e plut\xf4t que de redemander."},"tryAsk":"Essayez : <i>\xab \xc0 quelle heure est le Fajr demain \xe0 Orlando ? \xbb</i> \xb7 <i>\xab Dans quelle direction est la qibla depuis Karachi ? \xbb</i> \xb7 <i>\xab Quelle est la date h\xe9girienne aujourd\u2019hui ? \xbb</i> \xb7 <i>\xab Combien de temps avant l\u2019Asr \xe0 Toronto, hanafite ? \xbb</i>","privacyH":"Donn\xe9es publiques uniquement","privacy":"Le serveur ne fournit que des informations publiques : heures de pri\xe8re, dates h\xe9giriennes, direction de la qibla et m\xe9thodes de calcul. Il ne demande aucun compte et ne peut ni voir ni modifier vos r\xe9glages Muslim Companion. Les fonctions qui agissent pour vous, comme lire votre propre programme d\u2019Athan, viendront plus tard et demanderont toujours votre connexion et votre accord. Consultez notre <a>politique de confidentialit\xe9</a>.","alexaCta":"Muslim Companion pour Alexa"}')}}]);